// Normalize one ManyChat message from Hakeem's FB+IG flow into a clean lead.
//
// Hakeem's ManyChat automation is fully scripted — it asks for a DESTINATION and a
// WHATSAPP NUMBER and nothing else. There is no AI in this path, so unlike the
// chat-and-capture bots there is no travel_date / pax / email to collect.
//
// ManyChat posts the literal merge tag (e.g. "{{cuf_destination}}") when a field is
// still empty, so those must be scrubbed or they land in the sheet as junk text.

const b = $('Webhook').first().json.body || {};

const clean = (v) => {
  v = (v == null ? '' : String(v)).trim();
  if (/\{\{.*\}\}/.test(v)) return '';       // unresolved ManyChat merge tag
  if (/^(null|undefined)$/i.test(v)) return '';
  return v;
};

// The Contact Id is the PREFERRED row key, but ManyChat's External Request only sends it
// when someone remembers to add the field — and a body without it used to throw here,
// silently dropping the whole lead. Proven on the Faheem flow on 2026-08-29:
// five leads were lost exactly this way before the fallback below existed.
const manychat_id = clean(b.ig_user_id) || clean(b.subscriber_id);

const destination = clean(b.destination);
const travel_date = clean(b.travel_date || b.travelDate);

// phone: digits only, strip a leading 00 international prefix
let phone_digits = clean(b.contact_number || b.phone || b.whatsapp_number).replace(/\D/g, '');
if (phone_digits.startsWith('00')) phone_digits = phone_digits.slice(2);
// Canonicalise to country-code form BEFORE it goes anywhere. This flow posts straight
// to /tms/api/ingest and never passes through the CRM Sync normalizer the other bots
// rely on, so an uncorrected '09876543210' would reach sales undiallable.
if (phone_digits.length === 11 && phone_digits.startsWith('0')) phone_digits = '91' + phone_digits.slice(1);
else if (phone_digits.length === 10 && /^[6-9]/.test(phone_digits)) phone_digits = '91' + phone_digits;
const phone_valid = phone_digits.length >= 11;

// Fall back to the canonicalised phone as the row key. It is the one value this flow
// always collects, so Append-or-Update still dedupes a returning contact — just on the
// number instead of the Contact Id. The 'phone:' prefix keeps the two key spaces apart,
// so a real Contact Id can never collide with a number.
const ig_user_id = manychat_id || (phone_digits ? 'phone:' + phone_digits : '');
if (!ig_user_id) {
  // Only unkeyable now: no Contact Id AND no phone at all. Such a row would duplicate
  // on every message, so it is still worth failing loudly.
  throw new Error('no ig_user_id/subscriber_id and no usable phone — cannot key the sheet row');
}

// Display format, matching the other flows: '+91 xxxxx xxxxx' for Indian mobiles.
let whatsapp_number = '';
if (phone_valid) {
  let d = phone_digits;
  if (d.length === 12 && d.startsWith('91')) d = d.slice(2);
  else if (d.length === 11 && d.startsWith('0')) d = d.slice(1);
  whatsapp_number = (d.length === 10 && /^[6-9]/.test(d))
    ? '+91 ' + d.slice(0, 5) + ' ' + d.slice(5)
    : '+' + phone_digits;
}

// Assignee must match the sheet values exactly — normalize casing/spelling drift.
const a = clean(b.assignee);
const assignee = /^jasmine$/i.test(a) ? 'Jasmine'
  : /^jen?s?n?ica$/i.test(a) ? 'Jensica'
  : a;

// Channel: Hakeem's account runs Facebook AND Instagram through ManyChat.
const rawCh = clean(b.channel).toLowerCase();
const channel = rawCh.includes('face') || rawCh === 'fb' ? 'facebook'
  : rawCh.includes('insta') || rawCh === 'ig' ? 'instagram'
  : 'instagram';

// A lead is ready for the CRM once we can NAME it and CALL it. That is everything
// this flow collects — gating on travel_date/pax/email (as the viral template does)
// would mean no Hakeem lead ever reaches the CRM.
const crm_ready = Boolean(destination && phone_valid);
const any_field = Boolean(destination || phone_digits);
const status = crm_ready ? 'qualified' : (any_field ? 'in_progress' : 'new');

const now = new Date();
const ist = new Date(now.getTime() + 5.5 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

return [{
  json: {
    ig_user_id,
    ig_username: clean(b.ig_username) || clean(b.username),
    name: clean(b.name) || clean(b.first_name),
    destination,
    travel_date,
    phone_digits,
    whatsapp_number,
    assignee,
    channel,
    status,
    crm_ready,
    ts: ist,
    step: clean(b.step),
    // 'Month YYYY' in IST — identical format to the other tabs in this spreadsheet.
    lead_date: (() => {
      const t = new Date(Date.now() + 5.5 * 3600 * 1000);
      return t.toLocaleString('en-US', { month: 'long', timeZone: 'UTC' }) + ' ' + t.getUTCFullYear();
    })(),
  },
}];

// Never let a later, emptier message blank out something we already captured.
// ManyChat fires this webhook at EVERY step, so the "destination" message carries no
// phone and the "phone" message may carry no destination. Without this, each step
// would overwrite the previous one's answer with ''.

const fresh = $('Normalize').first().json;
const rows = $('Lookup existing row').all();
const prev = (rows.length && rows[0].json && rows[0].json.ig_user_id) ? rows[0].json : {};

const keep = (a, b) => (a && String(a).trim() !== '') ? a : (b || '');

const destination     = keep(fresh.destination, prev.Destination);
const travel_date     = keep(fresh.travel_date, prev['Travel date']);
const phone_digits    = keep(fresh.phone_digits, String(prev.Number || '').replace(/\D/g, ''));
const whatsapp_number = keep(fresh.whatsapp_number, prev.Number);
const assignee        = keep(fresh.assignee, prev.Assignee);
const name            = keep(fresh.name, prev['Name']);
const ig_username     = keep(fresh.ig_username, prev.ig_username);
const lead_date       = keep(prev['Lead date'], fresh.lead_date);

const phone_valid = String(phone_digits).length >= 10;
const crm_ready   = Boolean(destination && phone_valid);
const status      = crm_ready ? 'qualified'
                  : ((destination || phone_digits) ? 'in_progress' : 'new');

// Keep the ORIGINAL first-contact timestamp once a row exists.
const first_contact_ts = keep(prev['Lead date'], fresh.lead_date);

// Only push to the CRM on the turn we BECOME ready, not on every later message.
const was_ready = String(prev.Status || prev.status || '') === 'qualified';
const push_now  = crm_ready && !was_ready;

return [{
  json: {
    ...fresh,
    name, ig_username, destination, travel_date, phone_digits, whatsapp_number, assignee,
    status, crm_ready, push_now, first_contact_ts, lead_date,
    notes: 'Hakeem FB/IG lead (ManyChat scripted flow). Destination: '
      + (destination || '-') + ' | Assigned to ' + (assignee || '-') + '.',
  },
}];
